package com.ynxweb4.video;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.Base64;import java.nio.charset.StandardCharsets;
public final class NativeProductStateTest {
 static final String A="ynx1"+"q".repeat(38),B="ynx1"+"p".repeat(38),NS="ynx.native-product-session.v2:"+"a".repeat(64);
 static String key(){byte[] key=new byte[33];key[0]=2;return Base64.getUrlEncoder().withoutPadding().encodeToString(key);}
 static class Memory implements NativeProductState.Persistence {String raw="";boolean fail;public String read(){return raw;}public void write(String next){if(fail)throw new IllegalStateException("original write unavailable");raw=next;}}
 static NativeProductState create(Memory m)throws Exception{return new NativeProductState(m,"original-native-device-id",key(),"os-protected");}
 static JSONObject target(JSONObject ctx,String binding)throws Exception{return new JSONObject().put("chainId","ynx_6423-1").put("platform","android").put("deviceAlgorithm","p256-sha256").put("productId","video").put("clientId","ynx-video-mobile-v1").put("applicationId",NativeProductState.APP).put("bundleId",JSONObject.NULL).put("packageId",NativeProductState.APP).put("origin","app://android/"+NativeProductState.APP).put("callback","ynxvideo://wallet-auth/callback").put("deviceId",ctx.getString("deviceId")).put("deviceKey",ctx.getString("deviceKey")).put("account",A).put("scopes",NativeProductState.originalNativeScopes()).put("sessionBinding",binding);}
 static String intent(JSONObject ctx,JSONObject target,String id)throws Exception{return new JSONObject().put("version",1).put("intentId",id.repeat(43)).put("scope",NativeProductState.revocationScope(ctx)).put("session",target==null?JSONObject.NULL:target).toString();}
 @Test public void coldRestartRetainsOriginalDeviceGenerationAndEncryptedEnvelopeBytes()throws Exception{Memory m=new Memory();NativeProductState original=create(m);original.selectAccount(A);JSONObject ctx=original.context();original.set(NS,NativeProductState.ROOT,"original-session-wire",ctx);String saved=m.raw;NativeProductState cold=create(m);assertEquals(2,cold.context().getLong("generation"));assertEquals(A,cold.context().getString("account"));assertEquals("original-session-wire",cold.get(NS,NativeProductState.ROOT,ctx));assertEquals(saved,m.raw);}
 @Test public void accountChangeInvalidatesEveryOriginalActionWithoutDeletingOldNamespace()throws Exception{Memory m=new Memory();NativeProductState state=create(m);state.selectAccount(A);JSONObject old=state.context();state.set(NS,NativeProductState.ROOT,"original-A",old);state.selectAccount(B);JSONObject current=state.context();assertEquals(3,current.getLong("generation"));assertThrows(SecurityException.class,()->state.get(NS,NativeProductState.ROOT,old));assertThrows(SecurityException.class,()->state.get(NS,NativeProductState.ROOT,current));assertThrows(SecurityException.class,()->state.withExpected(old,()->true));assertTrue(m.raw.contains("original-A"));state.selectAccount(A);assertEquals(4,state.context().getLong("generation"));assertThrows(SecurityException.class,()->state.get(NS,NativeProductState.ROOT,state.context()));}
 @Test public void pendingNegativeAuthoritySurvivesColdRestartAndBlocksSignAndOpen()throws Exception{Memory m=new Memory();NativeProductState state=create(m);JSONObject ctx=state.context();state.requestRevocation(NS,ctx);assertTrue(state.revocationRequested(NS,ctx));NativeProductState cold=create(m);assertTrue(cold.revocationRequested(NS,ctx));assertThrows(SecurityException.class,()->cold.withSigningExpected(ctx,()->"late signature/open"));}
 @Test public void exactTargetCleanupIsOneCommitAndRetainsNewerUnrelatedSession()throws Exception{Memory m=new Memory();NativeProductState state=create(m);JSONObject ctx=state.context(),old=target(ctx,"a".repeat(64)),newer=target(ctx,"b".repeat(64));String pending=intent(ctx,old,"q");state.set(NS,NativeProductState.ROOT,NativeProductState.canonical(newer),ctx);state.set(NS,NativeProductState.ROOT+":pending","newer-original-pending",ctx);state.requestRevocation(NS,ctx);assertEquals(pending,state.saveRevocationIntent(NS,NativeProductState.ROOT+":revoke",pending,ctx));state.finishRevocationIntent(NS,NativeProductState.ROOT+":revoke",pending,ctx);assertEquals(NativeProductState.canonical(newer),state.get(NS,NativeProductState.ROOT,ctx));assertEquals("newer-original-pending",state.get(NS,NativeProductState.ROOT+":pending",ctx));assertNull(state.get(NS,NativeProductState.ROOT+":revoke",ctx));assertFalse(state.revocationRequested(NS,ctx));}
 @Test public void cleanupOfExactOriginalTargetRemovesOnlyOriginalCancelledRecords()throws Exception{Memory m=new Memory();NativeProductState state=create(m);JSONObject ctx=state.context(),target=target(ctx,"a".repeat(64));String pending=intent(ctx,target,"q");state.set(NS,NativeProductState.ROOT,NativeProductState.canonical(target),ctx);for(String suffix:new String[]{"pending","return","completion"})state.set(NS,NativeProductState.ROOT+":"+suffix,"original-cancelled",ctx);state.requestRevocation(NS,ctx);state.saveRevocationIntent(NS,NativeProductState.ROOT+":revoke",pending,ctx);state.finishRevocationIntent(NS,NativeProductState.ROOT+":revoke",pending,ctx);assertNull(state.get(NS,NativeProductState.ROOT,ctx));for(String suffix:new String[]{"pending","return","completion","revoke"})assertNull(state.get(NS,NativeProductState.ROOT+":"+suffix,ctx));assertFalse(create(m).revocationRequested(NS,ctx));}
 @Test public void changedIntentAndFailedCleanupPreserveOriginalNegativeAuthority()throws Exception{Memory m=new Memory();NativeProductState state=create(m);JSONObject ctx=state.context();String pending=intent(ctx,null,"q");state.requestRevocation(NS,ctx);state.saveRevocationIntent(NS,NativeProductState.ROOT+":revoke",pending,ctx);String saved=m.raw;assertThrows(SecurityException.class,()->state.finishRevocationIntent(NS,NativeProductState.ROOT+":revoke",intent(ctx,null,"p"),ctx));assertEquals(saved,m.raw);m.fail=true;assertThrows(Exception.class,()->state.finishRevocationIntent(NS,NativeProductState.ROOT+":revoke",pending,ctx));assertEquals(saved,m.raw);assertThrows(SecurityException.class,state::context);assertTrue(create(m).revocationRequested(NS,ctx));}
 @Test public void targetUpgradePreservesOriginalIntentIdAndRefusesReplacement()throws Exception{Memory m=new Memory();NativeProductState state=create(m);JSONObject ctx=state.context();String first=intent(ctx,null,"q"),bound=intent(ctx,target(ctx,"a".repeat(64)),"q");assertEquals(first,state.saveRevocationIntent(NS,NativeProductState.ROOT+":revoke",first,ctx));assertEquals(first,state.saveRevocationIntent(NS,NativeProductState.ROOT+":revoke",intent(ctx,null,"p"),ctx));assertEquals(bound,state.saveRevocationIntent(NS,NativeProductState.ROOT+":revoke",bound,ctx));}
 @Test public void malformedContextAndWrongScopeCannotRewriteOriginalEvidence()throws Exception{Memory m=new Memory();NativeProductState state=create(m);JSONObject ctx=state.context();String before=m.raw;assertThrows(SecurityException.class,()->state.set(NS,"foreign-product-key","credential",ctx));assertThrows(SecurityException.class,()->state.set("ynx.native-product-session.v2:wrong",NativeProductState.ROOT,"credential",ctx));JSONObject bad=new JSONObject(intent(ctx,null,"q")).put("scope","b".repeat(64));assertThrows(SecurityException.class,()->state.saveRevocationIntent(NS,NativeProductState.ROOT+":revoke",bad.toString(),ctx));assertEquals(before,m.raw);m.raw="broken-original-record";assertThrows(Exception.class,()->create(m));assertEquals("broken-original-record",m.raw);}
 @Test public void originalCanonicalSigningBytesBindDomainProductDeviceAccountAndRegisteredVideoScopes()throws Exception{Memory m=new Memory();NativeProductState state=create(m);state.selectAccount(A);JSONObject ctx=state.context(),subject=target(ctx,"a".repeat(64)).put("chainId","ynx_6423-1").put("platform","android");String text="YNX_PRODUCT_SESSION_CHALLENGE_V2\n"+NativeProductState.canonical(subject);JSONObject input=new JSONObject().put("purpose","challenge").put("algorithm","p256-sha256").put("deviceKey",key()).put("payload",Base64.getUrlEncoder().withoutPadding().encodeToString(text.getBytes(StandardCharsets.UTF_8)));assertArrayEquals(text.getBytes(StandardCharsets.UTF_8),NativeProductState.signBytes(input,ctx));for(int i=0;i<4;i++){JSONObject altered=new JSONObject(subject.toString());if(i==0)altered.put("account",B);if(i==1)altered.put("origin","https://foreign.invalid");if(i==2)altered.put("scopes",new JSONArray().put("identity:read"));if(i==3)altered.put("deviceId","another-original-device");String raw="YNX_PRODUCT_SESSION_CHALLENGE_V2\n"+NativeProductState.canonical(altered);JSONObject rejected=new JSONObject(input.toString()).put("payload",Base64.getUrlEncoder().withoutPadding().encodeToString(raw.getBytes(StandardCharsets.UTF_8)));assertThrows(Exception.class,()->NativeProductState.signBytes(rejected,ctx));}JSONObject spaced=new JSONObject(input.toString()).put("payload",Base64.getUrlEncoder().withoutPadding().encodeToString(("YNX_PRODUCT_SESSION_CHALLENGE_V2\n "+NativeProductState.canonical(subject)).getBytes(StandardCharsets.UTF_8)));assertThrows(Exception.class,()->NativeProductState.signBytes(spaced,ctx));}
 @Test public void walletOpeningCannotPromptForIdentityOrForeignNativeTuple()throws Exception{Memory m=new Memory();NativeProductState state=create(m);state.selectAccount(A);JSONObject ctx=state.context(),request=target(ctx,"a".repeat(64));request.remove("account");NativeProductState.checkWalletRequest(request,ctx);JSONObject seller=new JSONObject(request.toString()).put("scopes",new JSONArray().put("account:read").put("identity:read"));assertThrows(SecurityException.class,()->NativeProductState.checkWalletRequest(seller,ctx));JSONObject wrongChain=new JSONObject(request.toString()).put("chainId",6423);assertThrows(Exception.class,()->NativeProductState.checkWalletRequest(wrongChain,ctx));}
 @Test public void negativeAuthorityAllowsOnlyPersistedOriginalTargetRemoteRevoke()throws Exception{Memory m=new Memory();NativeProductState state=create(m);JSONObject ctx=state.context(),target=target(ctx,"a".repeat(64));state.set(NS,NativeProductState.ROOT,NativeProductState.canonical(target),ctx);state.requestRevocation(NS,ctx);state.saveRevocationIntent(NS,NativeProductState.ROOT+":revoke",intent(ctx,target,"q"),ctx);JSONObject proof=new JSONObject(target.toString()).put("version","2").put("method","POST").put("path","/v2/product-sessions/revoke").put("bodyDigest","44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a");String text="YNX_PRODUCT_SESSION_HTTP_PROOF_V2\n"+NativeProductState.canonical(proof);JSONObject input=new JSONObject().put("purpose","http-proof").put("algorithm","p256-sha256").put("deviceKey",key()).put("payload",Base64.getUrlEncoder().withoutPadding().encodeToString(text.getBytes(StandardCharsets.UTF_8)));int[] signed={0};assertEquals("original-revoke-signature",state.sign(input,ctx,true,bytes->{signed[0]++;assertArrayEquals(text.getBytes(StandardCharsets.UTF_8),bytes);return "original-revoke-signature";}));assertEquals(1,signed[0]);for(int i=0;i<4;i++){JSONObject bad=new JSONObject(proof.toString());if(i==0)bad.put("path","/api/creator/tracks");if(i==1)bad.put("bodyDigest","b".repeat(64));if(i==2)bad.put("sessionBinding","b".repeat(64));if(i==3)bad.put("account",B);String raw="YNX_PRODUCT_SESSION_HTTP_PROOF_V2\n"+NativeProductState.canonical(bad);JSONObject changed=new JSONObject(input.toString()).put("payload",Base64.getUrlEncoder().withoutPadding().encodeToString(raw.getBytes(StandardCharsets.UTF_8)));assertThrows(Exception.class,()->state.sign(changed,ctx,true,bytes->{signed[0]++;return "forbidden";}));}assertEquals(1,signed[0]);assertTrue(state.revocationRequested(NS,ctx));}
 @Test public void canonicalStringsMatchOriginalSDKWithoutHTMLOrUnicodeRewriting()throws Exception{assertEquals("\"</script>中\u2028\"",NativeProductState.canonical("</script>中\u2028"));assertEquals("\"\\ud800\"",NativeProductState.canonical("\ud800"));assertEquals("{\"a\":1,\"b\":\"\\n\"}",NativeProductState.canonical(new JSONObject().put("b","\n").put("a",1)));}
}
